import{j as s}from"./vendor-motion-CgKT7xo3.js";import{c as n}from"./Footer-DDrUWguI.js";import"./vendor-react-Cc8UVYhI.js";const o=[["path",{d:"M5 12h14",key:"1ays0h"}],["path",{d:"M12 5v14",key:"s699le"}]],a=n("plus",o),i=[{question:"Как начать работать с Барори Парк?",answer:"Оставьте заявку на сайте или напишите нам в мессенджер. Менеджер уточнит ваш город, документы и желаемый формат работы, подберет подходящее направление и поможет с оформлением."},{question:"Почему стоит подключаться через Барори Парк?",answer:"Поможем выбрать сервис и формат работы под ваш город, разобраться с документами и при необходимости оформить самозанятость. После старта остаёмся на связи по вопросам работы, выплат и бонусной программы. В спорных и сложных ситуациях не оставляем вас один на один с проблемой — помогаем найти решение и защищаем ваши интересы."},{question:"Можно ли работать только по выходным?",answer:"Да. Можно выходить на смены только по выходным, в свободные дни или совмещать подработку с основной работой. Доступные варианты зависят от города и выбранного направления."},{question:"Можно ли подключиться не гражданам РФ?",answer:"Да, в некоторых направлениях это возможно. Условия зависят от гражданства, документов, статуса пребывания и требований конкретного сервиса. Менеджер проверит все до оформления и подскажет доступные варианты."},{question:"Обязательно оформлять самозанятость?",answer:"Не всегда. Это зависит от выбранного сервиса и формата работы. Если самозанятость потребуется, поможем оформить ее и разобраться с документами."},{question:"Барори Парк подключает только к Яндексу?",answer:"Нет. Мы подключаем к нескольким сервисам и направлениям: Яндекс Такси, Яндекс Доставка, Яндекс Еда, Яндекс Смены, Купер, ТопГоу и другим."},{question:"Нужен ли опыт для старта?",answer:"Во многих курьерских и сменных направлениях опыт не требуется. Для работы водителем могут действовать требования к возрасту, стажу и документам — менеджер заранее проверит, подходите ли вы под условия, и предложит подходящие варианты."}],h=()=>s.jsx("section",{id:"faq",className:"home-section home-tint",children:s.jsxs("div",{className:"container home-faq-grid",children:[s.jsxs("div",{children:[s.jsx("p",{className:"home-eyebrow",children:"Поможем разобраться"}),s.jsx("h2",{className:"home-heading",children:"Вопросы и ответы"}),s.jsx("p",{className:"home-description",children:"Все, что важно знать перед стартом."})]}),s.jsx("div",{className:"home-faq-list",children:i.map(e=>s.jsxs("details",{className:"group",children:[s.jsxs("summary",{children:[e.question,s.jsx(a,{size:20,className:"shrink-0 transition-transform group-open:rotate-45"})]}),s.jsx("p",{children:e.answer})]},e.question))})]})});export{i as HOME_FAQ,h as SeoLandingContent};
